controllerSelect.addEventListener('change',()=>{syncPreferredTarget();syncExportLabel();syncAdvancedOptions()});targetSelect.addEventListener('change',()=>{syncExportLabel();syncAdvancedOptions();refreshNamingButton();const info=generationEngine()?.targetInfo?.(targetSelect.value);if(integrationTarget()&&info){statusEl.className='codegen-status '+(info.state==='warning'?'warning':'ok');statusEl.innerHTML=`<b>${info.state==='warning'?'REQUISITO PENDENTE':'DESTINO COMPATÍVEL'}</b><span>${esc(info.reason)}</span>`}});rainmakerInput?.addEventListener('change',syncAdvancedOptions);syncExportLabel();syncAdvancedOptions();$$('[data-action="codegen"]').forEach(b=>b.addEventListener('click',open));$$('[data-codegen-close]',modal).forEach(b=>b.addEventListener('click',close));modal.addEventListener('click',e=>{if(e.target===modal)close()});
